// #Sireum

package factory_flow.Factory_Flow

import org.sireum._
import art._
import factory_flow._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait FlowLedger_Api {
  def id: Art.BridgeId
  def authorization_Id : Art.PortId
  def contextToReadiness_Id : Art.PortId
  def contextToOutcome_Id : Art.PortId
  def protectionContext_Id : Art.PortId
  def snapshotToOutcome_Id : Art.PortId
  def snapshotToStatus_Id : Art.PortId
  def lineCommand_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var contextToReadiness: Factory_Flow.FlowContext = $

  def put_contextToReadiness(value : Factory_Flow.FlowContext) : Unit = {
    Contract(
      Modifies(contextToReadiness),
      Ensures(
        contextToReadiness == value
      )
    )
    Spec {
      contextToReadiness = value
    }

    Art.putValue(contextToReadiness_Id, Factory_Flow.FlowContext_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var contextToOutcome: Factory_Flow.FlowContext = $

  def put_contextToOutcome(value : Factory_Flow.FlowContext) : Unit = {
    Contract(
      Modifies(contextToOutcome),
      Ensures(
        contextToOutcome == value
      )
    )
    Spec {
      contextToOutcome = value
    }

    Art.putValue(contextToOutcome_Id, Factory_Flow.FlowContext_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var protectionContext: Factory_Flow.ProtectionContext = $

  def put_protectionContext(value : Factory_Flow.ProtectionContext) : Unit = {
    Contract(
      Modifies(protectionContext),
      Ensures(
        protectionContext == value
      )
    )
    Spec {
      protectionContext = value
    }

    Art.putValue(protectionContext_Id, Factory_Flow.ProtectionContext_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var snapshotToOutcome: Factory_Flow.FlowSnapshot = $

  def put_snapshotToOutcome(value : Factory_Flow.FlowSnapshot) : Unit = {
    Contract(
      Modifies(snapshotToOutcome),
      Ensures(
        snapshotToOutcome == value
      )
    )
    Spec {
      snapshotToOutcome = value
    }

    Art.putValue(snapshotToOutcome_Id, Factory_Flow.FlowSnapshot_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var snapshotToStatus: Factory_Flow.FlowSnapshot = $

  def put_snapshotToStatus(value : Factory_Flow.FlowSnapshot) : Unit = {
    Contract(
      Modifies(snapshotToStatus),
      Ensures(
        snapshotToStatus == value
      )
    )
    Spec {
      snapshotToStatus = value
    }

    Art.putValue(snapshotToStatus_Id, Factory_Flow.FlowSnapshot_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var lineCommand: Factory_Flow.LineFlowCommand = $

  def put_lineCommand(value : Factory_Flow.LineFlowCommand) : Unit = {
    Contract(
      Modifies(lineCommand),
      Ensures(
        lineCommand == value
      )
    )
    Spec {
      lineCommand = value
    }

    Art.putValue(lineCommand_Id, Factory_Flow.LineFlowCommand_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class FlowLedger_Initialization_Api (
  val id: Art.BridgeId,
  val authorization_Id : Art.PortId,
  val contextToReadiness_Id : Art.PortId,
  val contextToOutcome_Id : Art.PortId,
  val protectionContext_Id : Art.PortId,
  val snapshotToOutcome_Id : Art.PortId,
  val snapshotToStatus_Id : Art.PortId,
  val lineCommand_Id : Art.PortId) extends FlowLedger_Api

@datatype class FlowLedger_Operational_Api (
  val id: Art.BridgeId,
  val authorization_Id : Art.PortId,
  val contextToReadiness_Id : Art.PortId,
  val contextToOutcome_Id : Art.PortId,
  val protectionContext_Id : Art.PortId,
  val snapshotToOutcome_Id : Art.PortId,
  val snapshotToStatus_Id : Art.PortId,
  val lineCommand_Id : Art.PortId) extends FlowLedger_Api {

  // Logika spec var representing port state for incoming data port
  @spec var authorization: Factory_Flow.AuthorizationFact = $

  def get_authorization() : Option[Factory_Flow.AuthorizationFact] = {
    Contract(
      Ensures(
        Res == Some(authorization)
      )
    )
    val value : Option[Factory_Flow.AuthorizationFact] = Art.getValue(authorization_Id) match {
      case Some(Factory_Flow.AuthorizationFact_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port authorization.  Expecting 'Factory_Flow.AuthorizationFact_Payload' but received ${v}")
        None[Factory_Flow.AuthorizationFact]()
      case _ => None[Factory_Flow.AuthorizationFact]()
    }
    return value
  }
}
